#include <stdint.h>
#include <inttypes.h>
#include <stddef.h>
#include <stdlib.h>
#include <limits.h>

int main(void) {
    size_t capacity = 4, head = 0, tail = 0, accepted = 0;
    for (size_t i = 0; i < 4; ++i) {
        size_t next = (head + 1) % capacity;
        if (next == tail)
            break;
        head = next;
        ++accepted;
    }
    printf("accepted=%zu full=%d\n", accepted, (head + 1) % capacity == tail);
    return 0;
}

